class Solution:
    def countElements(self, nums: List[int]) -> int:
        nums.sort()
        i, j = 0, len(nums) - 1
        while i < len(nums) and nums[i] == nums[0]:
            i += 1
        while j >= 0 and nums[j] == nums[-1]:
            j -= 1
        return max(0, j - i + 1)

