class Solution {
    public int countElements(int[] nums) {
        int lo = nums[0], hi = nums[0];
        for (int x : nums) {
            lo = Math.min(lo, x);
            hi = Math.max(hi, x);
        }
        if (lo == hi) return 0;
        int cnt = 0;
        for (int x : nums)
            if (x != lo && x != hi) cnt++;
        return cnt;
    }
}

